using System.Text.RegularExpressions;

namespace QuickCode.Quickcode.Infrastructure.Web.Helpers;

/// <summary>
/// Shared password strength rules for Identity, Gateway, and Portal.
/// </summary>
public static class PasswordPolicy
{
    public const int MinLength = 8;
    public const int MaxLength = 100;

    public const string RequirementsText =
        "At least 8 characters, including uppercase, lowercase, a number, and a symbol.";

    public const string ErrorMessage =
        "Password must be at least 8 characters and include an uppercase letter, a lowercase letter, a number, and a symbol.";

    public const string ComplexityPattern =
        @"^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^A-Za-z0-9]).{8,100}$";

    private static readonly Regex ComplexityRegex = new(ComplexityPattern, RegexOptions.Compiled);

    public static PasswordValidationResult Validate(string? password)
    {
        var errors = new List<string>();
        password ??= string.Empty;

        if (password.Length < MinLength)
            errors.Add($"Password must be at least {MinLength} characters long.");

        if (password.Length > MaxLength)
            errors.Add($"Password cannot exceed {MaxLength} characters.");

        if (!password.Any(char.IsUpper))
            errors.Add("Password must contain at least one uppercase letter.");

        if (!password.Any(char.IsLower))
            errors.Add("Password must contain at least one lowercase letter.");

        if (!password.Any(char.IsDigit))
            errors.Add("Password must contain at least one number.");

        if (!password.Any(ch => !char.IsLetterOrDigit(ch)))
            errors.Add("Password must contain at least one symbol.");

        return new PasswordValidationResult
        {
            IsValid = errors.Count == 0,
            Errors = errors
        };
    }

    public static bool IsStrong(string? password) => ComplexityRegex.IsMatch(password ?? string.Empty);

